package org.mpi_sws.jmc.checker

import org.mpi_sws.jmc.util.FileUtil

/**
 * The JmcModelCheckerReport class represents a report generated by the JMC model checker.
 */
class JmcModelCheckerReport(reportPath: String?) {
    private val reportData = HashMap<String, Any?>()

    val reportPath: String = reportPath!!

    fun setupReportPath() {
        FileUtil.unsafeEnsurePath(reportPath)
    }

    var totalTimeMillis: Long?
        get() = getParam<Long>("totalTimeMillis")
        set(totalTimeMillis) {
            setParam("totalTimeMillis", totalTimeMillis)
        }

    var errorIteration: Int?
        get() = getParam<Int>("errorIteration")
        set(errorIteration) {
            setParam("errorIteration", errorIteration)
        }

    var errorMessage: String?
        get() = getParam<String>("errorMessage")
        set(errorMessage) {
            setParam("errorMessage", errorMessage)
        }

    var replaySeed: Long?
        get() = getParam<Long>("replaySeed")
        set(replaySeed) {
            setParam("replaySeed", replaySeed)
        }

    var totalIterations: Int?
        get() {
            val o = getParam<Any>("totalIterations") ?: return 0
            return o as Int
        }
        set(totalIterations) {
            setParam("totalIterations", totalIterations)
        }

    var blockedIterations: Int?
        get() {
            val o = getParam<Any>("blockedIterations") ?: return 0
            return o as Int
        }
        set(blockedIterations) {
            setParam("blockedIterations", blockedIterations)
        }

    fun setParam(key: String, value: Any?) {
        reportData[key] = value
    }

    fun <T> getParam(key: String): T? {
        if (!reportData.containsKey(key)) {
            return null
        }
        return reportData[key] as T?
    }
}
